    [80+Math.sin(t*0.45+3)*110,100+Math.cos(t*0.65+2)*70,0.11,2.1,6],
    [400+Math.cos(t*0.55+1)*80,140+Math.sin(t*0.75+4)*60,0.085,1.8,7]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
