  const act=aS/8,inh=iS/8,het=hS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+Math.sin(sy*0.05+t)*2+t*1.5)*0.15+Math.sin(sy*0.07+Math.cos(sx*0.04+t)*2-t*1.3)*0.15;
