  const reaction=Math.tanh((act-inh*0.7+het*0.3+bg*0.3+spiral)*2.2);
  const fReact=Math.tanh((Math.sin(sx*0.2+t*1.2)*Math.cos(sy*0.18-t*0.9)-Math.sin((sx-sy)*0.15+t*0.7)*0.6)*2.0)*0.2;
  const blend=reaction*0.65+cell*0.2+fReact*0.15,v=blend*0.5+0.5;
